export async function createSecretStore(
  options: SecretStoreOptions,
): Promise<SecretStore> {
  const { storage, masterPassword } = options;

  const SALT_KEY = "\x00__salt__";
  const SECRET_PREFIX = "\x00__secret__\x00";

  const enc = new TextEncoder();
  const dec = new TextDecoder();

  function bytesToBase64(bytes: Uint8Array): string {
    let binary = "";
    const chunkSize = 0x8000;
    for (let i = 0; i < bytes.length; i += chunkSize) {
      binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
    }
    return btoa(binary);
  }

  function base64ToBytes(b64: string): Uint8Array {
    const binary = atob(b64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }

  // Ensure salt exists
  let saltB64 = await storage.get(SALT_KEY);
  if (saltB64 === undefined) {
    const salt = crypto.getRandomValues(new Uint8Array(32));
    saltB64 = bytesToBase64(salt);
    await storage.set(SALT_KEY, saltB64);
  }

  const salt = base64ToBytes(saltB64);

  // Derive AES-GCM key
  const passwordKey = await crypto.subtle.importKey(
    "raw",
    enc.encode(masterPassword),
    "PBKDF2",
    false,
    ["deriveKey"]
  );

  const aesKey = await crypto.subtle.deriveKey(
    {
      name: "PBKDF2",
      salt,
      iterations: 100000,
      hash: "SHA-256",
    },
    passwordKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"]
  );

  function secretKeyFor(owner: string, name: string): string {
    return SECRET_PREFIX + JSON.stringify([owner, name]);
  }

  async function encrypt(plaintext: string): Promise<string> {
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const data = enc.encode(plaintext);
    const ciphertextBuf = await crypto.subtle.encrypt(
      { name: "AES-GCM", iv },
      aesKey,
      data
    );
    const ciphertext = new Uint8Array(ciphertextBuf);
    const combined = new Uint8Array(12 + ciphertext.length);
    combined.set(iv, 0);
    combined.set(ciphertext, 12);
    return bytesToBase64(combined);
  }

  async function decrypt(stored: string): Promise<string> {
    const combined = base64ToBytes(stored);
    if (combined.length < 12) {
      throw new Error("Invalid ciphertext");
    }
    const iv = combined.subarray(0, 12);
    const ciphertext = combined.subarray(12);
    const plaintextBuf = await crypto.subtle.decrypt(
      { name: "AES-GCM", iv },
      aesKey,
      ciphertext
    );
    return dec.decode(plaintextBuf);
  }

  return {
    async put(owner: string, name: string, value: string): Promise<void> {
      const key = secretKeyFor(owner, name);
      const encrypted = await encrypt(value);
      await storage.set(key, encrypted);
    },

    async get(owner: string, name: string): Promise<string | undefined> {
      const key = secretKeyFor(owner, name);
      const stored = await storage.get(key);
      if (stored === undefined) {
        return undefined;
      }
      try {
        return await decrypt(stored);
      } catch {
        throw new Error("Failed to decrypt secret: data may have been tampered with or the password is incorrect");
      }
    },

    async list(owner: string): Promise<string[]> {
      const allKeys = await storage.keys();
      const names: string[] = [];
      for (const key of allKeys) {
        if (!key.startsWith(SECRET_PREFIX)) continue;
        try {
          const json = key.slice(SECRET_PREFIX.length);
          const parsed = JSON.parse(json);
          if (Array.isArray(parsed) && parsed.length === 2 && typeof parsed[0] === "string" && typeof parsed[1] === "string") {
            if (parsed[0] === owner) {
              names.push(parsed[1]);
            }
          }
        } catch {
          // Skip unparseable keys
        }
      }
      names.sort();
      return names;
    },

    async remove(owner: string, name: string): Promise<boolean> {
      const key = secretKeyFor(owner, name);
      const stored = await storage.get(key);
      if (stored === undefined) {
        return false;
      }
      await storage.delete(key);
      return true;
    },
  };
}
